import{_ as i,o as t,c as l,ae as a}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Searchable Ledger and Filtering API","description":"","frontmatter":{"work_package_id":"WP03","title":"Searchable Ledger and Filtering API","lane":"done","dependencies":["WP02"],"base_branch":"024-audit-logging-and-session-replay-WP02","base_commit":"c3003b5354b8a4232e87053fc5731dadad357570","created_at":"2026-03-01T13:34:36.641585+00:00","subtasks":["T009","T010","T011","T012","T013"],"phase":"Phase 2 - Audit Querying","assignee":"","agent":"claude-haiku","shell_pid":"76365","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/024-audit-logging-and-session-replay/tasks/WP03-searchable-ledger-and-filtering.md","filePath":"specs/024-audit-logging-and-session-replay/tasks/WP03-searchable-ledger-and-filtering.md"}'),r={name:"specs/024-audit-logging-and-session-replay/tasks/WP03-searchable-ledger-and-filtering.md"};function s(n,e,o,c,d,u){return t(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="work-package-prompt-wp03-searchable-ledger-and-filtering-api" tabindex="-1">Work Package Prompt: WP03 - Searchable Ledger and Filtering API <a class="header-anchor" href="#work-package-prompt-wp03-searchable-ledger-and-filtering-api" aria-label="Permalink to &quot;Work Package Prompt: WP03 - Searchable Ledger and Filtering API&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Implement the searchable audit ledger with multi-dimensional filtering.</li><li>Support correlation ID chain traversal for cross-lane/session debugging.</li><li>Deliver real-time ledger updates via bus subscription.</li><li>Expose ledger queries through runtime API endpoints.</li></ul><p>Success criteria:</p><ul><li>Queries return matching events within 500ms (p95) for datasets up to 1 million events.</li><li>Correlation ID search returns the complete event chain for 99.9% of traced operations.</li><li>Real-time updates push new matching events to active queries without polling.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/024-audit-logging-and-session-replay/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/024-audit-logging-and-session-replay/spec.md</code></li><li>WP02 output: Ring buffer, SQLite store.</li></ul><p>Constraints:</p><ul><li>Search latency &lt; 500ms (p95) for 1M events.</li><li>Correlation chain traversal must be complete (99.9% accuracy).</li><li>Real-time updates via bus, not polling.</li><li>Keep files under repository limits (target &lt;=350 lines, hard &lt;=500).</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP03</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t009-implement-auditledger-with-multi-dimensional-filtering" tabindex="-1">Subtask T009 - Implement AuditLedger with multi-dimensional filtering <a class="header-anchor" href="#subtask-t009-implement-auditledger-with-multi-dimensional-filtering" aria-label="Permalink to &quot;Subtask T009 - Implement AuditLedger with multi-dimensional filtering&quot;">​</a></h3><ul><li>Purpose: Provide a high-level query interface over the audit storage that supports all spec-required filter dimensions.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/ledger.ts</code>.</li><li>Define <code>AuditFilter</code> interface: <ul><li><code>workspaceId</code>: optional string</li><li><code>laneId</code>: optional string</li><li><code>sessionId</code>: optional string</li><li><code>actor</code>: optional string</li><li><code>eventType</code>: optional string or string[]</li><li><code>correlationId</code>: optional string</li><li><code>timeRange</code>: optional <code>{ from: Date, to: Date }</code></li><li><code>limit</code>: number (default 100, max 1000)</li><li><code>offset</code>: number (default 0)</li></ul></li><li>Implement <code>AuditLedger</code> class that: <ul><li>First checks the ring buffer for recent events matching the filter.</li><li>Falls back to SQLite for historical events.</li><li>Merges results from both sources, deduplicating by event ID.</li><li>Returns events in chronological order.</li></ul></li><li>Implement <code>search(filter: AuditFilter): AuditEvent[]</code> as the primary query method.</li><li>Implement <code>count(filter: AuditFilter): number</code> for result count without full data.</li><li>Optimize query execution: use SQLite indexes for all filterable dimensions; skip SQLite for time-range queries where all results are within ring buffer window.</li><li>Add query timing metrics.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/ledger.ts</code></li></ul></li><li>Acceptance: <ul><li>All filter dimensions work correctly.</li><li>Results merged from ring buffer and SQLite with deduplication.</li><li>Chronological ordering maintained.</li><li>Query timing &lt; 500ms (p95) for 1M events.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t010-implement-correlation-id-chain-traversal" tabindex="-1">Subtask T010 - Implement correlation ID chain traversal <a class="header-anchor" href="#subtask-t010-implement-correlation-id-chain-traversal" aria-label="Permalink to &quot;Subtask T010 - Implement correlation ID chain traversal&quot;">​</a></h3><ul><li>Purpose: Enable operators to trace a complete chain of related events across lanes and sessions for debugging and incident response.</li><li>Steps: <ol><li>In <code>AuditLedger</code>, implement <code>getCorrelationChain(correlationId: string): AuditEvent[]</code>.</li><li>Start from the given correlation ID, query all events with that ID.</li><li>If any returned events reference a parent correlation ID (via metadata), recursively follow the chain.</li><li>Return the complete chain in chronological order.</li><li>Handle circular references: track visited correlation IDs and break cycles with a warning.</li><li>Handle broken chains: log a warning if a referenced correlation ID has no matching events.</li><li>Optimize: pre-fetch likely related events based on workspace/lane/session context.</li><li>Test: create a chain of 10 correlated events across 3 lanes, traverse from the last event, verify all 10 returned in order.</li><li>Test: broken chain (missing middle event) returns available events with warning.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/ledger.ts</code> (add method)</li></ul></li><li>Acceptance: <ul><li>Complete chains returned for 99.9% of traced operations.</li><li>Circular references handled gracefully.</li><li>Broken chains produce warnings but do not crash.</li><li>Results in chronological order.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t011-implement-real-time-ledger-updates" tabindex="-1">Subtask T011 - Implement real-time ledger updates <a class="header-anchor" href="#subtask-t011-implement-real-time-ledger-updates" aria-label="Permalink to &quot;Subtask T011 - Implement real-time ledger updates&quot;">​</a></h3><ul><li>Purpose: Enable the UI to show new matching events as they arrive without polling.</li><li>Steps: <ol><li>In <code>AuditLedger</code>, implement a subscription mechanism: <ul><li><code>subscribe(filter: AuditFilter, callback: (event: AuditEvent) =&gt; void): Unsubscribe</code>.</li></ul></li><li>The ledger subscribes to the bus for new audit events.</li><li>For each new event, check it against all active filter subscriptions.</li><li>If the event matches a subscription&#39;s filter, invoke the callback with the event.</li><li>Ensure callbacks are non-blocking (async invocation).</li><li>Implement <code>Unsubscribe</code> function to clean up subscriptions.</li><li>Handle high event throughput: batch notifications at configurable intervals (e.g., 100ms) to avoid overwhelming the UI.</li><li>Test: subscribe with a workspace filter, emit matching and non-matching events, verify only matching events are delivered.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/ledger.ts</code> (add subscription)</li></ul></li><li>Acceptance: <ul><li>Real-time updates for matching events.</li><li>Non-matching events not delivered.</li><li>Subscriptions cleanly removable.</li><li>Batched delivery for performance.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t012-create-ledger-query-api-endpoints" tabindex="-1">Subtask T012 - Create ledger query API endpoints <a class="header-anchor" href="#subtask-t012-create-ledger-query-api-endpoints" aria-label="Permalink to &quot;Subtask T012 - Create ledger query API endpoints&quot;">​</a></h3><ul><li>Purpose: Expose the audit ledger to the desktop UI and external consumers via runtime API.</li><li>Steps: <ol><li>Add ledger query endpoints to the runtime API surface (following the existing pattern in <code>apps/runtime/src/</code>): <ul><li><code>GET /audit/events</code> — search with filter parameters (workspace, lane, session, actor, type, time range, correlation ID, limit, offset).</li><li><code>GET /audit/events/:correlationId/chain</code> — correlation chain traversal.</li><li><code>GET /audit/events/count</code> — count matching events.</li><li><code>WS /audit/events/subscribe</code> — WebSocket endpoint for real-time updates with filter.</li></ul></li><li>Parse query parameters and construct <code>AuditFilter</code> objects.</li><li>Return results as JSON arrays with pagination metadata (total count, offset, limit).</li><li>WebSocket endpoint sends new events as JSON messages when they match the subscription filter.</li><li>Add request validation: reject invalid filter parameters with clear error messages.</li><li>Add rate limiting: max 100 queries/minute per client.</li><li>Document the API endpoints with request/response schemas.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/audit/api.ts</code> (or integrated into existing API router)</li></ul></li><li>Acceptance: <ul><li>All query endpoints return correct results.</li><li>WebSocket subscription delivers real-time updates.</li><li>Pagination works correctly.</li><li>Invalid parameters rejected with clear errors.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t013-search-performance-tests" tabindex="-1">Subtask T013 - Search performance tests <a class="header-anchor" href="#subtask-t013-search-performance-tests" aria-label="Permalink to &quot;Subtask T013 - Search performance tests&quot;">​</a></h3><ul><li>Purpose: Validate that ledger search meets the 500ms p95 target for large datasets and that correlation chain traversal is reliable.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/audit/search-performance.test.ts</code>.</li><li>Insert 1 million audit events into SQLite with realistic distribution across 10 workspaces, 50 lanes, 100 sessions.</li><li>Benchmark filter queries: <ul><li>Single workspace filter: measure p95 latency, assert &lt; 500ms.</li><li>Time range filter (1 hour window): measure p95, assert &lt; 500ms.</li><li>Combined workspace + actor + event type filter: measure p95, assert &lt; 500ms.</li><li>Correlation ID search: measure p95, assert &lt; 500ms.</li></ul></li><li>Benchmark correlation chain traversal: <ul><li>Create 100 chains of 5-20 events each.</li><li>Traverse each chain, verify completeness.</li><li>Measure p95 traversal time, assert &lt; 500ms.</li></ul></li><li>Verify real-time subscription delivery latency: emit event, measure time to callback invocation.</li><li>Document all measurements.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/audit/search-performance.test.ts</code></li></ul></li><li>Acceptance: <ul><li>All search queries &lt; 500ms p95 for 1M events.</li><li>Correlation chain traversal 99.9% complete.</li><li>Measurements documented.</li></ul></li><li>Parallel: Yes (after T009-T012 are functional).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Performance benchmarks with 1M event dataset.</li><li>Correlation chain completeness verification.</li><li>Real-time subscription delivery tests.</li><li>API endpoint integration tests.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: SQLite queries are slow without proper indexing.</li><li>Mitigation: Comprehensive indexes on all filter dimensions; EXPLAIN QUERY PLAN verification.</li><li>Risk: Real-time subscription overwhelms the UI with high event throughput.</li><li>Mitigation: Batch notifications at configurable intervals.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm all filter dimensions are supported and indexed.</li><li>Confirm correlation chain traversal handles edge cases.</li><li>Confirm real-time subscriptions are non-blocking.</li><li>Confirm API endpoints are documented and validated.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z – system – lane=planned – Prompt created.</li><li>2026-03-01T13:34:37Z – claude-haiku – shell_pid=76365 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:35:56Z – claude-haiku – shell_pid=76365 – lane=done – Implemented: Searchable ledger with multi-dimensional filtering, correlation chain traversal, real-time subscriptions, and HTTP API</li></ul>',30)])])}const m=i(r,[["render",s]]);export{h as __pageData,m as default};
